import { z } from "zod";

/** The most subsections one section may have; raise it when the artist needs more. */
export const maxSubsections = 30;

/** Generated by the client, so a section keeps its id while it is renamed. */
const sectionIdSchema = z.uuid();

const sectionTitleSchema = z.string().trim().min(1).max(50);

/** The path parameters of a request about one section. */
export const sectionParamsSchema = z.object({
  id: sectionIdSchema,
});

/**
 * The key two titles are compared by: the visitor reads "Графика" and "графика" as the same
 * section, so they may not both be there.
 */
export function titleKey(title: string): string {
  return title.toLocaleLowerCase("ru");
}

const titleCollator = new Intl.Collator("ru");

/** Sorts by title in the Russian alphabet, as the site and the admin list sections. */
export function byTitle(a: { title: string }, b: { title: string }): number {
  return titleCollator.compare(a.title, b.title);
}

/**
 * A section as the client sends it, to create one or to replace a saved one. The subsections are
 * listed in any order: the site shows them by title. A saved subsection left out is deleted.
 */
export const sectionBodySchema = z
  .strictObject({
    title: sectionTitleSchema,
    subsections: z
      .array(
        z.strictObject({
          /** Generated by the client, like the id of a section. */
          id: sectionIdSchema,
          title: sectionTitleSchema,
        }),
      )
      .max(maxSubsections),
  })
  .superRefine(({ subsections }, context) => {
    const ids = new Set<string>();
    const titles = new Set<string>();

    subsections.forEach(({ id, title }, index) => {
      if (ids.has(id)) {
        context.addIssue({
          code: "custom",
          message: "Each id must appear once",
          path: ["subsections", index, "id"],
        });
      }

      if (titles.has(titleKey(title))) {
        context.addIssue({
          code: "custom",
          message: "Another subsection has this title",
          path: ["subsections", index, "title"],
        });
      }

      ids.add(id);
      titles.add(titleKey(title));
    });
  });

const subsectionSchema = z.object({
  id: z.string(),
  title: z.string(),
});

/**
 * A section as stored in Firestore, in its own document of the `gallerySections` collection, and
 * as the API returns it without the id. Only the shape is checked: the rules above apply when a
 * section is saved, so tightening a rule later never makes a saved section unreadable.
 */
export const storedSectionSchema = z.object({
  title: z.string(),
  /** Sorted by title. */
  subsections: z.array(subsectionSchema),
});

/** A section as the API returns it. */
export const sectionSchema = storedSectionSchema.extend({
  id: z.string(),
});

export const sectionResponseSchema = z.object({ section: sectionSchema });

export const sectionsResponseSchema = z.object({
  /** Sorted by title. */
  sections: z.array(sectionSchema),
});

export type SectionParams = z.infer<typeof sectionParamsSchema>;
export type SectionBody = z.infer<typeof sectionBodySchema>;
export type StoredSection = z.infer<typeof storedSectionSchema>;
export type Section = z.infer<typeof sectionSchema>;
export type SectionResponse = z.infer<typeof sectionResponseSchema>;
export type SectionsResponse = z.infer<typeof sectionsResponseSchema>;
